#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-or-later
set -eu
if [ "$#" -ne 1 ]; then echo "Usage: CXX=m68k-amigaos-g++ $0 OUTPUT" >&2; exit 2; fi
src=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
mkdir -p -- "$(dirname -- "$1")"
"${CXX:-m68k-amigaos-g++}" -m68040 -m68881 -std=c++17 -O2 -Wall -Wextra -Werror \
 -fno-exceptions -fno-rtti -fno-builtin -fno-tree-loop-distribute-patterns \
 "$src/rules_text.cpp" "$src/citizens_text.cpp" "$src/original_map.cpp" "$src/original_game.cpp" "$src/original_faction.cpp" "$src/original_world.cpp" "$src/prototype.cpp" "$src/movement.cpp" "$src/saved_speed.cpp" "$src/world_unit_stats.cpp" "$src/world_unit_support.cpp" "$src/vehicle_stack.cpp" "$src/tile_yields.cpp" "$src/world_tile_yields.cpp" "$src/technology_effects.cpp" "$src/world_fresh_tile_yields.cpp" "$src/world_worker_radius.cpp" "$src/world_terraform_ecology.cpp" "$src/world_stable_intake.cpp" "$src/base_nutrients.cpp" "$src/world_fresh_nutrients.cpp" "$src/world_convoy_nutrients.cpp" "$src/base_minerals.cpp" "$src/world_fresh_minerals.cpp" "$src/world_commerce.cpp" "$src/world_citizen_energy.cpp" "$src/world_police.cpp" "$src/world_pacifism.cpp" "$src/base_psych.cpp" "$src/world_psych_internal.cpp" "$src/energy_inefficiency.cpp" "$src/base_energy.cpp" "$src/world_energy.cpp" "$src/facility_availability.cpp" "$src/world_facility_options.cpp" "$src/production_retool.cpp" "$src/world_production_retool.cpp" "$src/local_production_session.cpp" "$src/local_accounting.cpp" "$src/local_accounting_snapshot.cpp" "$src/human_worker_allocation.cpp" "$src/world_human_allocation.cpp" "$src/local_workers.cpp" "$src/local_workers_snapshot.cpp" "$src/world_movement_price.cpp" "$src/move_budget.cpp" "$src/world_actions.cpp" "$src/local_session_actions.cpp" "$src/load_record_repairs.cpp" "$src/phase_snapshot.cpp" "$src/initialized_snapshot.cpp" "$src/resumed_commands.cpp" "$src/local_unit_skip.cpp" "$src/local_unit_skip_probe.cpp" -o "$1"
